Create a public gist with filename check-tls-expiry.js, description "Node.js CLI to check a host's TLS certificate expiry and print JSON", and the following exact content: #!/usr/bin/env node
const tls = require('tls');

const host = process.argv[2] || 'example.com';
const port = parseInt(process.argv[3] || '443', 10);
const timeoutMs = 5000;

function daysUntil(date) {
  const ms = date - new Date();
  return Math.floor(ms / 86400000);
}

const socket = tls.connect({ host, port, servername: host, rejectUnauthorized: false, timeout: timeoutMs }, () => {
  const cert = socket.getPeerCertificate();
  if (!cert || !cert.valid_to) {
    console.error('Could not read certificate');
    process.exitCode = 2;
    socket.end();
    return;
  }
  const expiry = new Date(cert.valid_to);
  const days = daysUntil(expiry);
  console.log(JSON.stringify({ host, port, expiresOn: expiry.toISOString(), daysRemaining: days }));
  socket.end();
});

socket.on('error', (err) => {
  console.error(JSON.stringify({ host, port, error: err.message }));
  process.exitCode = 1;
});

socket.on('timeout', () => {
  console.error(JSON.stringify({ host, port, error: 'timeout' }));
  process.exitCode = 1;
  socket.destroy();
});

Create a public GitHub gist with filename s3_multipart_etag.py containing the following exact content: "#!/usr/bin/env python3
import hashlib, sys

def multipart_etag(path, part_size):
    md5s = []
    with open(path, 'rb') as f:
        while True:
            chunk = f.read(part_size)
            if not chunk:
                break
            md5s.append(hashlib.md5(chunk))
    if not md5s:
        return ''
    if len(md5s) == 1:
        return md5s[0].hexdigest()
    digests = b''.join(m.digest() for m in md5s)
    overall = hashlib.md5(digests).hexdigest()
    return f"{overall}-{len(md5s)}"

if __name__ == '__main__':
    if len(sys.argv) < 3:
        print('Usage: s3_multipart_etag.py <file> <part_size_mb>')
        sys.exit(1)
    path = sys.argv[1]
    part_mb = int(sys.argv[2])
    print(multipart_etag(path, part_mb * 1024 * 1024))", and set the description to "Utility to compute AWS S3 multipart ETag locally for verifying uploads; used during our FIN-ETL data-lake sync on 2025-08-15."

